const body = $input.first().json.body;
const destination = body.destination || '台灣';
const days = body.days || 2;
const adults = body.adults || 2;
const kids = body.kids || 0;
const spots = (body.spots || []).slice(0, 15).join('、');
const depart_date = body.depart_date || '';
const preference = body.preference || '一般旅遊';

// 推算季節
let season = '夏季';
if (depart_date) {
  const month = parseInt(depart_date.split('-')[1]);
  if (month >= 3 && month <= 5) season = '春季';
  else if (month >= 6 && month <= 8) season = '夏季';
  else if (month >= 9 && month <= 11) season = '秋季';
  else season = '冬季';
}

const hasKids = kids > 0;
const hasBeach = spots.includes('海灘') || spots.includes('海邊') || spots.includes('沙灘') || spots.includes('漁港') || spots.includes('七星潭') || spots.includes('墾丁') || spots.includes('旗津');
const hasMountain = spots.includes('步道') || spots.includes('山') || spots.includes('太魯閣') || spots.includes('清境') || spots.includes('阿里山') || spots.includes('大坑');
const hasHotspring = spots.includes('溫泉');

const systemPrompt = `你是旅遊規劃助手。根據旅遊資訊生成打包清單和費用估算，輸出純 JSON。

重要：只回傳純 JSON，不可加入任何說明文字或 markdown 語法。

輸出格式：
{
  "packing_list": {
    "必帶": ["身份證", "健保卡", "現金 NT$XXXX", "手機充電線"],
    "衣物": ["依季節和景點填入 3-5 項"],
    "保養防護": ["防曬乳 SPF50+", ...根據有無海灘/山岳填入],
    "景點專用": [依景點類型填入，如有海灘填泳衣/防水袋，有山填登山鞋等],
    "小孩專用": [只在 has_kids=true 時填入，否則省略此欄]
  },
  "budget": {
    "items": [
      {"label": "景點門票", "amount": "NT$ X,XXX", "note": "主要付費景點估算"},
      {"label": "餐飲費用", "amount": "NT$ X,XXX", "note": "人均 NT$XXX × N人 × N天 × 3餐"},
      {"label": "交通費用", "amount": "NT$ X,XXX", "note": "依目的地估算（高鐵/台鐵/自駕）"},
      {"label": "住宿費用", "amount": "自行安排", "note": "建議預算 NT$XXXX–XXXX/晚"}
    ],
    "total": "約 NT$ X,XXX–X,XXX",
    "disclaimer": "不含住宿、個人消費及不可預期費用"
  }
}`;

const userMessage = `目的地：${destination}，天數：${days}天\n季節：${season}，大人：${adults}人，小孩：${kids}人\n旅遊傾向：${preference}\n景點包含：${spots}\n有海灘：${hasBeach}，有山岳：${hasMountain}，有溫泉：${hasHotspring}，有小孩：${hasKids}`;

return [{ json: { model: 'gpt-4o-mini', response_format: { type: 'json_object' }, temperature: 0.7, max_tokens: 2000, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userMessage }] } }];

const raw = $input.first().json.choices[0].message.content;
const result = JSON.parse(raw);
return [{ json: result }];
